const sessionId = $input.first().json.sessionId || 'session-' + Date.now();
const timestamp = new Date().toISOString();
const agentOutput = $input.first().json.output || '';
const chatHistory = $input.first().json.chatHistory || [];

// Count UNKNOWN fields
const missingFields = (agentOutput.match(/UNKNOWN/g) || []).length;
const fieldsCollected = 12 - missingFields;
const guardrailTriggered = missingFields > 0 ? 'Y' : 'N';

// Extract user identity from output
const nameMatch = agentOutput.match(/- Name: (.+)/);
const titleMatch = agentOutput.match(/- Title: (.+)/);
const roleMatch = agentOutput.match(/- Project Role: (.+)/);
const purposeMatch = agentOutput.match(/- Purpose: (.+)/);

// Compute diff — capture any PM feedback in prior turns
const pmFeedback = chatHistory
  .filter(m => m.role === 'user' && !m.content.includes('👍') && m.content !== 'Go Ahead')
  .map(m => m.content)
  .join(' | ');

const logEntry = {
  timestamp,
  session_id: sessionId,
  agent: 'Task1_IntakeAgent',
  // Learning Field 1: User Profile
  user_name: nameMatch ? nameMatch[1].trim() : 'UNKNOWN',
  user_title: titleMatch ? titleMatch[1].trim() : 'UNKNOWN',
  user_role: roleMatch ? roleMatch[1].trim() : 'UNKNOWN',
  // Learning Field 2: Reason for Interaction
  reason_for_interaction: purposeMatch ? purposeMatch[1].trim() : 'UNKNOWN',
  // Learning Field 3: Approvals vs Disapprovals
  approval_count: 0,
  disapproval_count: 0,
  // Learning Field 4: Changes and Feedback
  pm_feedback_and_changes: pmFeedback || 'None',
  // Supporting metrics
  fields_collected: fieldsCollected,
  fields_missing: missingFields,
  guardrail_triggered: guardrailTriggered,
  outcome: 'Pending_PM_Approval',
  raw_output_snapshot: agentOutput.substring(0, 500)
};

return [{ json: { logEntry, agentOutput, sessionId } }];

// Update approval count in learning sheet
const logEntry = $input.first().json.logEntry;
logEntry.approval_count = 1;
logEntry.outcome = 'Approved';
return [{ json: { ...$input.first().json, logEntry } }];

// Update disapproval count and capture PM feedback
const logEntry = $input.first().json.logEntry;
const feedback = $input.first().json.chatInput || '';
logEntry.disapproval_count += 1;
logEntry.pm_feedback_and_changes = (logEntry.pm_feedback_and_changes || '') + ' | Revision: ' + feedback;
logEntry.outcome = 'Revision_Requested';
return [{ json: { ...$input.first().json, logEntry, feedback } }];
